def parse_quoted_field(line, start):
    length = len(line)
    field = ""
    escaped = False

    for end in range(start, length):
        char = line[end]
        if escaped:
            field += char
            escaped = False
        elif char == '"':
            return field, end
        elif char == '\\':
            escaped = True
        else:
            field += char

    raise ValueError("Unmatched quote in quoted field")

